import{_ as d,o as r,c as a,ag as o}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"天涯神贴知识库 · 总目录","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/handbook/00_知识库总目录.md","filePath":"topics/tianya/handbook/00_知识库总目录.md"}'),e={name:"topics/tianya/handbook/00_知识库总目录.md"};function _(n,t,i,s,l,c){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="天涯神贴知识库-·-总目录" tabindex="-1">天涯神贴知识库 · 总目录 <a class="header-anchor" href="#天涯神贴知识库-·-总目录" aria-label="Permalink to &quot;天涯神贴知识库 · 总目录&quot;">​</a></h1><blockquote><p>2026-11-06 由 138 帖 / 约 20 万页原文提炼。不是导读，是<strong>知识本体</strong>：论证链、方法步骤、关键数字、适用与失效条件，全部标注来源帖号（方括号数字 = 文件名编号）。 单文件合集版：<code>天涯神贴知识库_合集.md</code>（本目录全部内容合并）。</p></blockquote><table tabindex="0"><thead><tr><th>文件</th><th>内容</th><th>字数</th></tr></thead><tbody><tr><td>01_房价与土地财政的底层逻辑</td><td>利益分析法三步法与两个完整推演、三级垄断模型、调控五阶段剧本、房价决定模型7条、炒房融资6渠道、房产税转嫁机制、点位兑现表、失效清单与公理检验三问</td><td>~6700</td></tr><tr><td>02_房产实战手册</td><td>三因子选城、流动性体温计、租金覆盖月供、信仰→可检验命题改写、救市信号清单、中介话术拆解、2019卖点复盘，附速查卡</td><td>~5800</td></tr><tr><td>03_货币蓄水池与债务周期</td><td>蓄水池完整链条与历次换池表、外储之锚与锁游资推演、明斯基三阶段、通缩自我强化环、银行基层玩法、15项监测指标、2021-2026验证与失效</td><td>~6900</td></tr><tr><td>04_趋势预测方法论</td><td>命中率分层定律、利益分析五步预测流程（两次完整示范）、周期定位法、人口→需求推演、通胀通缩八条判定清单、六种失效模式、普通人纪律七条</td><td>~5100</td></tr><tr><td>05_投资交易知识手册</td><td>配资爆仓数学、三套可执行短线规则、贪嗔痴慢疑映射表、赌场负期望推导、庄家视角、币圈货币演化论、做透三步法、12条风控检查表</td><td>~8700</td></tr><tr><td>06_职场与社会生存知识</td><td>平台评估决策树、利用价值定价法、裁员信号清单、陷阱工作三问、生意场识人、热恋周期论、泰国物价数据表与四维比价法</td><td>~4100</td></tr><tr><td>07_防骗与识局知识</td><td>骗局通用结构、八类骗术逐类流程与破绽点、加盟四铁律、炒作五征兆、三段可打印防骗检查清单</td><td>~4400</td></tr><tr><td>08_民俗志怪知识库</td><td>十四条民俗/行业知识（成色三档：行业真实/民俗传说/小说演绎）、灵异文五大配方写作法、14部名著用招对照表</td><td>~7000</td></tr><tr><td>09_刑侦司法与行业实录知识</td><td>刑警办案五步推演、悬案三断点、检察官实锤标准与司法精神病鉴定、殡葬流程与行规、考古处置链，全部标注【实录】/【演绎】</td><td>~6200</td></tr><tr><td>10_历史军事知识</td><td>太平洋战争决策链与日本战败结构性原因、抗战正面战场、绥靖批判与斯大林格勒论战、川军史、大人物之死的政治规律、民间史论校验法</td><td>见文</td></tr><tr><td>11_玄学商战与考据知识</td><td>四门预测术框架（易/奇门/太乙/六壬）、面相改行为论、周易起卦实操、筹码类型学、慧商学院营销体系、红楼时间线考据法示范</td><td>见文</td></tr></tbody></table><h2 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h2><ul><li><strong>当手册用</strong>：01-05（经济与投资）+ 07（防骗）可直接对照现实操作</li><li><strong>当教材读</strong>：03 和 04 是整套&quot;天涯经济学&quot;的心法，先读这两份再看其他</li><li><strong>当资料库查</strong>：08/09/10/11 按需检索，成色标注帮你区分真知识与传说</li><li>所有失效条件（尤其 01/03 的 2021 年后部分）是这套知识的保鲜膜，别扔</li></ul>',5)])])}const u=d(e,[["render",_]]);export{p as __pageData,u as default};
